1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import {
5	  getAudit,
6	  getAuditTimeline,
7	  type AuditEvent,
8	  type AuditTimelineEvent,
9	} from "@/src/lib/api";
10	
11	const ACTOR_LABEL: Record<string, string> = {
12	  ai: "AI",
13	  human: "Human",
14	  system: "System",
15	};
16	
17	function formatTime(value: string) {
18	  return new Intl.DateTimeFormat("en", {
19	    month: "short",
20	    day: "2-digit",
21	    hour: "2-digit",
22	    minute: "2-digit",
23	  }).format(new Date(value));
24	}
25	
26	function payloadPreview(payload: Record<string, unknown>) {
27	  const text = JSON.stringify(payload, null, 2);
28	  return text.length > 2200 ? `${text.slice(0, 2200)}\n...` : text;
29	}
30	
31	export function AuditTrail({
32	  scenarioId,
33	  requirementId,
34	  compact = false,
35	}: {
36	  scenarioId?: string;
37	  requirementId?: string;
38	  compact?: boolean;
39	}) {
40	  const [timeline, setTimeline] = useState<AuditTimelineEvent[]>([]);
41	  const [events, setEvents] = useState<AuditEvent[]>([]);
42	  const [error, setError] = useState<string | null>(null);
43	  const [loading, setLoading] = useState(true);
44	
45	  useEffect(() => {
46	    let cancelled = false;
47	    const filter = { scenarioId, requirementId };
48	    Promise.all([getAuditTimeline(filter), getAudit(filter)])
49	      .then(([nextTimeline, nextEvents]) => {
50	        if (cancelled) return;
51	        setTimeline(nextTimeline);
52	        setEvents(nextEvents);
53	        setError(null);
54	      })
55	      .catch((err: Error) => {
56	        if (!cancelled) setError(err.message);
57	      })
58	      .finally(() => {
59	        if (!cancelled) setLoading(false);
60	      });
61	    return () => {
62	      cancelled = true;
63	    };
64	  }, [requirementId, scenarioId]);
65	
66	  const bySeq = new Map(events.map((event) => [event.seq, event]));
67	
68	  if (loading) {
69	    return <p className="rounded-md border border-slate-200 bg-white p-4 text-sm text-slate-500">Loading audit trail...</p>;
70	  }
71	
72	  if (error) {
73	    return (
74	      <div className="rounded-md border border-rose-300 bg-rose-50 p-4 text-sm text-rose-800">
75	        {error}
76	      </div>
77	    );
78	  }
79	
80	  if (timeline.length === 0) {
81	    return (
82	      <div className="rounded-md border border-slate-200 bg-white p-4 text-sm text-slate-500">
83	        No audit events for this selection yet.
84	      </div>
85	    );
86	  }
87	
88	  return (
89	    <div className={compact ? "space-y-3" : "space-y-4"}>
90	      {timeline.map((item) => {
91	        const event = bySeq.get(item.seq);
92	        return (
93	          <article
94	            key={item.seq}
95	            className="rounded-lg border border-slate-200 bg-white p-4 shadow-sm"
96	          >
97	            <div className="flex flex-wrap items-start justify-between gap-3">
98	              <div>
99	                <p className="text-sm font-semibold text-[#262626]">{item.sentence}</p>
100	                <p className="mt-1 text-xs text-slate-500">
101	                  #{item.seq} · {formatTime(item.ts)} · {ACTOR_LABEL[item.actor.type] ?? item.actor.type}:{" "}
102	                  {item.actor.name}
103	                </p>
104	              </div>
105	              <span className="rounded-full border border-slate-300 bg-slate-50 px-3 py-1 text-xs font-semibold text-slate-700">
106	                {item.event_type}
107	              </span>
108	            </div>
