  feedback: number;
  study: number;
  sales: number;
  options: number;
  web: number;
  external: number;
  badge: string;
}

export interface Scenario {
  id: string;
  derivative: string;
  model_name: string;
  market: string;
  countries: string[];
  competitors: string[];
  successor_horizon: string;
  data_coverage?: DataCoverage;
  badge?: string;
  warnings?: string[];
  headline_numbers?: {
    evidence: number;
    signals: number;
    requirements: number;
    top_title: string | null;
  };
}

export interface Funnel {
  evidence: number;
  signals: number;
  requirements: number;
  approved: number;
  note?: string;
  generated_at?: string | null;
}

export interface OverviewView {
  scenario_id: string;
  funnel: Funnel;
  top3: Array<{
    id: string;
    title: string;
    score: number;
    rank: number;
    evidence_level: EvidenceLevel;
    level_label?: string;
    badges?: string[];
  }>;
  level_distribution: Record<EvidenceLevel, number>;
  warnings: string[];
  source_mix: DataCoverage;
  generated_at: string | null;
}

export interface RequirementDetail {
  requirement: Requirement;
  signals: Signal[];
  evidence: Evidence[];
  history: AuditEvent[];
}

export interface WaterfallStep {
  factor: string;

